{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-aOOAfR/src/nodes.js","content":"// Value node constructors. Every node in the parsed document is one of:
//   table          - a Map<string, Node>, may be marked headerDefined
//   arrayOfTables  - an array of table nodes
//   array          - an array of value nodes
//   string         - a JS string
//   integer        - a BigInt
//   float          - a JS number
//   boolean        - a JS boolean

export function makeTable() {
  return { kind: 'table', map: new Map(), headerDefined: false }
}

export function makeArrayOfTables() {
  return { kind: 'arrayOfTables', items: [] }
}

export function makeArray(items) {
  return { kind: 'array', items }
}

export function makeString(value) {
  return { kind: 'string', value }
}

export function makeInteger(value) {
  return { kind: 'integer', value }
}

export function makeFloat(value) {
  return { kind: 'float', value }
}

export function makeBoolean(value) {
  return { kind: 'boolean', value }
}

export function typeOf(node) {
  switch (node.kind) {
    case 'table':
      return 'table'
    case 'arrayOfTables':
    case 'array':
      return 'array'
    default:
      return node.kind
  }
}

// Compare two strings by Unicode code point, not by UTF-16 code unit.
export function compareCodePoint(a, b) {
  const ai = Array.from(a)
  const bi = Array.from(b)
  const len = Math.min(ai.length, bi.length)
  for (let i = 0; i < len; i++) {
    const ca = ai[i].codePointAt(0)
    const cb = bi[i].codePointAt(0)
    if (ca !== cb) return ca - cb
  }
  return ai.length - bi.length
}

export function sortedKeys(map) {
  return Array.from(map.keys()).sort(compareCodePoint)
}
"}

