{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-aOOAfR/src/tokenizer.js","content":"import { fail, reasons } from './errors.js'
import { makeArray, makeBoolean, makeFloat, makeInteger, makeString, makeTable } from './nodes.js'
import { insertKey } from './document.js'

const BARE_NAME_RE = /[A-Za-z0-9_-]/
const INT_RE = /^[+-]?\d+(?:_\d+)*$/
const FLOAT_RE =
  /^[+-]?\d+(?:_\d+)*(?:\.\d+(?:_\d+)*(?:[eE][+-]?\d+(?:_\d+)*)?|[eE][+-]?\d+(?:_\d+)*)$/

function isSpace(c) {
  return c === ' ' || c === '\t'
}

export function skipSpaces(line, pos) {
  while (pos < line.length && isSpace(line[pos])) pos++
  return pos
}

// Skip spaces/tabs; if a comment starts here, the rest of the line is
// considered consumed (returns line.length).
export function skipWsAndComment(line, pos) {
  pos = skipSpaces(line, pos)
  if (pos < line.length && (line[pos] === '#' || line[pos] === ';')) {
    return line.length
  }
  return pos
}

function parseBasicString(line, pos) {
  // line[pos] === '"'
  pos++
  let out = ''
  while (true) {
    if (pos >= line.length) fail(reasons.unterminatedString())
    const c = line[pos]
    if (c === '"') {
      pos++
      return { value: out, pos }
    }
    if (c === '\\') {
      pos++
      if (pos >= line.length) fail(reasons.unterminatedString())
      const e = line[pos]
      switch (e) {
        case '"':
          out += '"'
          pos++
          break
        case '\\':
          out += '\\'
          pos++
          break
        case 'n':
          out += '\n'
          pos++
          break
        case 't':
          out += '\t'
          pos++
          break
        case 'r':
          out += '\r'
          pos++
          break
        case '0':
          out += '\0'
          pos++
          break
        case 'u': {
          const hex = line.slice(pos + 1, pos + 5)
          if (hex.length === 4 && /^[0-9A-Fa-f]{4}$/.test(hex)) {
            out += String.fromCharCode(parseInt(hex, 16))
            pos += 5
          } else {
            fail(reasons.invalidEscape('u'))
          }
          break
        }
        default:
          fail(reasons.invalidEscape(e))
      }
